using System;using System.Collections.Generic;using System.IO;using System.Net.Http;using System.Threading;using System.Threading.Tasks;using System.Windows;using System.Windows.Controls;using System.Windows.Input;using System.Windows.Media;using System.Windows.Media.Imaging;using System.Windows.Shapes;
namespace StudyDesk {
 public class LocationMap:Grid {
  readonly Canvas canvas=new Canvas{Background=new SolidColorBrush(Color.FromRgb(237,242,249)),ClipToBounds=true};readonly HttpClient http=new HttpClient();readonly SemaphoreSlim requests=new SemaphoreSlim(2);CancellationTokenSource redraw=new CancellationTokenSource();double centerLat=34,centerLon=105;int zoom=4;bool network;Point? dragStart;double dragX,dragY;double? latitude,longitude;public Action<double,double> Selected;
  public static Point Project(double lat,double lon,int z){double size=256*Math.Pow(2,z);lat=Math.Max(-85.05112878,Math.Min(85.05112878,lat));double sin=Math.Sin(lat*Math.PI/180);return new Point((lon+180)/360*size,(.5-Math.Log((1+sin)/(1-sin))/(4*Math.PI))*size);}
  public static Point Unproject(double x,double y,int z){double size=256*Math.Pow(2,z);double lon=((x/size*360)%360+360)%360-180;double lat=Math.Atan(Math.Sinh(Math.PI*(1-2*y/size)))*180/Math.PI;return new Point(lat,lon);}
  public LocationMap(){Height=310;Children.Add(canvas);var controls=new StackPanel{Orientation=Orientation.Horizontal,HorizontalAlignment=HorizontalAlignment.Left,VerticalAlignment=VerticalAlignment.Top,Margin=new Thickness(10)};var online=new Button{Content="加载在线地图",Padding=new Thickness(12,7,12,7),Margin=new Thickness(0,0,8,0)};online.Click+=(s,e)=>{network=true;online.Content="在线地图已启用";Draw();};controls.Children.Add(online);foreach(int direction in new[]{1,-1}){int step=direction;var b=new Button{Content=step>0?"＋":"－",Padding=new Thickness(12,7,12,7),Margin=new Thickness(0,0,6,0)};b.Click+=(s,e)=>{zoom=Math.Max(2,Math.Min(18,zoom+step));Draw();};controls.Children.Add(b);}Children.Add(controls);var attribution=new TextBlock{Text="© OpenStreetMap contributors · WGS84",FontSize=11,Background=Brushes.White,Foreground=Brushes.DimGray,HorizontalAlignment=HorizontalAlignment.Right,VerticalAlignment=VerticalAlignment.Bottom,Padding=new Thickness(5),Cursor=Cursors.Hand};attribution.MouseLeftButtonUp+=(s,e)=>System.Diagnostics.Process.Start("https://www.openstreetmap.org/copyright");Children.Add(attribution);
   http.Timeout=TimeSpan.FromSeconds(12);http.DefaultRequestHeaders.UserAgent.ParseAdd("StudentTong/1.0");SizeChanged+=(s,e)=>Draw();Loaded+=(s,e)=>Draw();Unloaded+=(s,e)=>redraw.Cancel();canvas.MouseLeftButtonDown+=(s,e)=>{dragStart=e.GetPosition(canvas);Point p=Project(centerLat,centerLon,zoom);dragX=p.X;dragY=p.Y;canvas.CaptureMouse();};canvas.MouseMove+=(s,e)=>{if(!dragStart.HasValue||e.LeftButton!=MouseButtonState.Pressed)return;Point at=e.GetPosition(canvas),delta=new Point(at.X-dragStart.Value.X,at.Y-dragStart.Value.Y);Point pos=Unproject(dragX-delta.X,dragY-delta.Y,zoom);centerLat=pos.X;centerLon=pos.Y;Draw();};canvas.MouseLeftButtonUp+=(s,e)=>{if(!dragStart.HasValue)return;Point end=e.GetPosition(canvas);bool clicked=(end-dragStart.Value).Length<5;dragStart=null;canvas.ReleaseMouseCapture();if(clicked){Point c=Project(centerLat,centerLon,zoom);Point p=Unproject(c.X+end.X-canvas.ActualWidth/2,c.Y+end.Y-canvas.ActualHeight/2,zoom);latitude=p.X;longitude=p.Y;Draw();if(Selected!=null)Selected(p.X,p.Y);}};
  }
  public void Center(double lat,double lon){centerLat=lat;centerLon=lon;latitude=lat;longitude=lon;zoom=Math.Max(zoom,13);Draw();}
  void Draw(){if(canvas.ActualWidth<1||canvas.ActualHeight<1)return;redraw.Cancel();redraw=new CancellationTokenSource();var token=redraw.Token;canvas.Children.Clear();Point center=Project(centerLat,centerLon,zoom);double left=center.X-canvas.ActualWidth/2,top=center.Y-canvas.ActualHeight/2;int count=1<<zoom;
   if(network){for(int tx=(int)Math.Floor(left/256);tx<=(int)Math.Floor((left+canvas.ActualWidth)/256);tx++)for(int ty=(int)Math.Floor(top/256);ty<=(int)Math.Floor((top+canvas.ActualHeight)/256);ty++){if(ty<0||ty>=count)continue;int x=(tx%count+count)%count,y=ty,z=zoom;var tile=new Image{Width=256,Height=256};Canvas.SetLeft(tile,tx*256-left);Canvas.SetTop(tile,ty*256-top);canvas.Children.Add(tile);var task=Tile(tile,z,x,y,token);}}
   else{var label=new TextBlock{Text="点击选点，拖动移动地图。在线底图需点击上方加载；也可直接输入经纬度。",TextWrapping=TextWrapping.Wrap,Foreground=Brushes.SlateGray,Width=Math.Max(200,canvas.ActualWidth-60)};Canvas.SetLeft(label,24);Canvas.SetTop(label,85);canvas.Children.Add(label);}
   var cross=new TextBlock{Text="＋",FontSize=25,Foreground=Brushes.SlateGray};Canvas.SetLeft(cross,canvas.ActualWidth/2-12);Canvas.SetTop(cross,canvas.ActualHeight/2-19);canvas.Children.Add(cross);
   if(latitude.HasValue){Point mark=Project(latitude.Value,longitude.Value,zoom);var dot=new Ellipse{Width=15,Height=15,Fill=Brushes.RoyalBlue,Stroke=Brushes.White,StrokeThickness=3};Canvas.SetLeft(dot,mark.X-left-7);Canvas.SetTop(dot,mark.Y-top-7);canvas.Children.Add(dot);}
  }
  async Task Tile(Image target,int z,int x,int y,CancellationToken token){bool entered=false;try{await requests.WaitAsync(token);entered=true;string folder=System.IO.Path.Combine(Desktop.Root,"cache","maps",z.ToString(),x.ToString());string file=System.IO.Path.Combine(folder,y+".png");byte[] bytes;if(File.Exists(file)&&DateTime.UtcNow-File.GetLastWriteTimeUtc(file)<TimeSpan.FromDays(7))bytes=File.ReadAllBytes(file);else{using(var response=await http.GetAsync("https://tile.openstreetmap.org/"+z+"/"+x+"/"+y+".png",token)){response.EnsureSuccessStatusCode();bytes=await response.Content.ReadAsByteArrayAsync();token.ThrowIfCancellationRequested();Directory.CreateDirectory(folder);File.WriteAllBytes(file,bytes);}}token.ThrowIfCancellationRequested();using(var stream=new MemoryStream(bytes)){var bitmap=new BitmapImage();bitmap.BeginInit();bitmap.CacheOption=BitmapCacheOption.OnLoad;bitmap.StreamSource=stream;bitmap.EndInit();bitmap.Freeze();target.Source=bitmap;}}catch{}finally{if(entered)requests.Release();}}
 }
}

